(()=>{"use strict";
let rows=[],adminRows=[],sheetRows=[],loading=false,lastSheetFetch=0;
const norm=v=>String(v??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"_").replace(/^_+|_+$/g,"");
const bool=v=>["true","1","sim","yes","ativo","on","verdadeiro"].includes(String(v??"").trim().toLowerCase());
const num=v=>{const n=parseFloat(String(v??"").trim().replace(",","."));return Number.isFinite(n)?n:0};
function parseDateBR(value){const v=String(value??"").trim();if(!v)return null;let m=v.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?$/);if(m){const[,y,mo,d,h,mi,se="00"]=m,x=new Date(`${y}-${String(mo).padStart(2,"0")}-${String(d).padStart(2,"0")}T${String(h).padStart(2,"0")}:${mi}:${se}-03:00`);return Number.isNaN(x.getTime())?null:x}m=v.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?$/);if(m){const[,d,mo,y,h,mi,se="00"]=m,x=new Date(`${y}-${String(mo).padStart(2,"0")}-${String(d).padStart(2,"0")}T${String(h).padStart(2,"0")}:${mi}:${se}-03:00`);return Number.isNaN(x.getTime())?null:x}const x=new Date(v);return Number.isNaN(x.getTime())?null:x}
function parseTSV(text){const out=[];let row=[],cell="",quoted=false;const s=String(text??"").replace(/^\uFEFF/,"");for(let i=0;i<s.length;i++){const c=s[i],n=s[i+1];if(c==='"'){if(quoted&&n==='"'){cell+='"';i++}else quoted=!quoted}else if(c==='\t'&&!quoted){row.push(cell);cell=""}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&n==='\n')i++;row.push(cell);cell="";if(row.some(v=>String(v).trim()))out.push(row);row=[]}else cell+=c}row.push(cell);if(row.some(v=>String(v).trim()))out.push(row);return out}
function parseSheet(text){const table=parseTSV(text);if(table.length<2)return[];const head=table[0].map(norm),idx=aliases=>head.findIndex(h=>aliases.map(norm).includes(h));const map={titulo:idx(["torneio","titulo","evento","live"]),faseDia:idx(["fase_dia","fase_e_dia","fase","rodada"]),canal:idx(["canal","streamer","criador"]),url:idx(["url","link","live_url"]),categoria:idx(["categoria","tipo"]),ativo:idx(["ativo","ao_vivo","aovivo","live"]),data_hora:idx(["data_hora","datahora","data_e_hora","inicio","data"]),duracao:idx(["duracao","duracao_horas","horas"]),linkMode:idx(["link_mode","modo_link","liberar_link","disponibilidade_link"])};return table.slice(1).map((r,i)=>{const get=(k,fallback)=>map[k]>=0?r[map[k]]:r[fallback];return{id:`sheet-live-${i}`,titulo:String(get("titulo",0)??"").trim(),faseDia:String(map.faseDia>=0?get("faseDia",-1):"").trim(),canal:String(get("canal",1)??"").trim(),url:String(get("url",2)??"").trim(),categoria:String(get("categoria",3)??"mobile").trim().toLowerCase()||"mobile",ativo:bool(get("ativo",4)),data_hora:String(get("data_hora",5)??"").trim(),duracaoMinutos:Math.max(0,Math.round(num(get("duracao",6))*60)),linkMode:String(map.linkMode>=0?get("linkMode",-1):"always").trim().toLowerCase()==="schedule"?"schedule":"always",source:"sheet"}}).filter(r=>r.titulo.length>2)}
function parseAdmin(data){return Object.entries(data||{}).map(([id,raw])=>{const mins=raw?.duracaoMinutos!=null?Number(raw.duracaoMinutos):num(raw?.duracao)*60,links=(Array.isArray(raw?.links)?raw.links:Object.values(raw?.links||{})).map((x,i)=>({label:String(x?.label||x?.nome||x?.canal||`Alternativa ${i+1}`).trim(),url:String(x?.url||x?.link||"").trim()})).filter(x=>x.url);return{id:String(raw?.id||id),titulo:String(raw?.torneio||raw?.titulo||"").trim(),faseDia:String(raw?.faseDia||raw?.fase_dia||"").trim(),canal:String(raw?.canal||"").trim(),url:String(raw?.url||"").trim(),links,categoria:String(raw?.tipo||raw?.categoria||"mobile").trim().toLowerCase(),ativo:false,data_hora:String(raw?.inicio||raw?.data_hora||"").trim(),duracaoMinutos:Number.isFinite(mins)?Math.max(0,Math.round(mins)):0,linkMode:String(raw?.linkMode||"always").trim().toLowerCase()==="schedule"?"schedule":"always",source:"admin"}}).filter(r=>r.titulo.length>2&&r.data_hora)}
function liveKey(r){const d=parseDateBR(r.data_hora);return `${norm(r.titulo)}|${d?d.getTime():String(r.data_hora)}`}
function mergeRows(){const merged=new Map;sheetRows.forEach(r=>merged.set(liveKey(r),r));adminRows.forEach(r=>merged.set(liveKey(r),r));rows=Array.from(merged.values())}
function durationMinutes(r){return Math.max(0,Number(r.duracaoMinutos||0))}
function statusFor(r,now){const start=parseDateBR(r.data_hora),mins=durationMinutes(r),end=start&&mins>0?new Date(start.getTime()+mins*60000):null,inWindow=!!(start&&end&&now>=start&&now<=end),future=!!(start&&now<start);return{start,end,inWindow,future,isLive:!!(r.ativo||inWindow)}}
const UPCOMING_PAGE_SIZE=3;let upcomingVisible=3;
function resolveLiveUrl(value){const raw=String(value||"").trim();if(!raw)return"";try{const u=new URL(raw,location.href),host=u.hostname.toLowerCase().replace(/^www\./,"");if(host==="youtube.com"||host==="m.youtube.com"){let path=u.pathname.replace(/\/+$/,"");if(/^\/(?:@[^/]+|channel\/[^/]+|c\/[^/]+|user\/[^/]+)$/i.test(path)){u.pathname=path+"/live";u.search="";u.hash="";return u.toString()}if(/^\/(?:@[^/]+|channel\/[^/]+|c\/[^/]+|user\/[^/]+)\/streams$/i.test(path)){u.pathname=path.replace(/\/streams$/i,"/live");u.search="";u.hash="";return u.toString()}}return u.toString()}catch(e){return raw}}
function liveLinkAvailable(r,s,now,url=r.url){if(!url)return false;return r.linkMode!=="schedule"||!!(s.start&&now>=s.start)}
function liveLinks(r){const out=[];if(r.url)out.push({label:r.canal||"Principal",url:r.url});(r.links||[]).forEach((x,i)=>{if(x?.url&&!out.some(y=>y.url===x.url))out.push({label:x.label||`Alternativa ${i+1}`,url:x.url})});return out}
function buildLiveCard(r,s,now,labels){const allLinks=liveLinks(r),primary=allLinks.find(x=>liveLinkAvailable(r,s,now,x.url)),href=primary?resolveLiveUrl(primary.url):"",el=document.createElement(href?"a":"div");const visualClass=["mobile","emulador","emulator","misto"].includes(r.categoria)?"recomendada":r.categoria;el.className="live-card "+(s.isLive?`ativo ${visualClass}`:"agendado");if(href){el.target="_blank";el.rel="noopener noreferrer";el.href=href}else{el.style.cursor="default";if(allLinks.length&&r.linkMode==="schedule"&&s.future)el.title="Links liberados no horário de início"};let badge="";if(s.isLive){badge=labels[r.categoria]||"AO VIVO"}else{const ms=Math.max(0,s.start-now),totalMins=Math.ceil(ms/6e4),days=Math.floor(totalMins/1440),hours=Math.floor(totalMins%1440/60),mins=totalMins%60;if(totalMins<=15){badge="COMEÇA JÁ";el.classList.add("is-starting-soon")}else{const parts=[];if(days>0)parts.push(`${days}d`);if(hours>0||days>0)parts.push(`${hours}h`);parts.push(`${mins}min`);badge=`⏳ ${parts.join("")}`}}el.innerHTML=`<div class="live-dot"></div><div class="live-card-info"><div class="live-card-titulo"></div><div class="live-card-canal"></div></div><span class="live-card-badge"></span>`;el.querySelector(".live-card-titulo").textContent=r.titulo;el.querySelector(".live-card-canal").textContent=[r.faseDia,r.canal].filter(Boolean).join(" • ");el.querySelector(".live-card-badge").textContent=badge;const available=allLinks.filter(x=>liveLinkAvailable(r,s,now,x.url));if(available.length>1){const links=document.createElement("span");links.className="cff-live-alt-links";available.forEach((x,i)=>{const b=document.createElement("span");b.className="cff-live-alt-link";b.setAttribute("role","link");b.tabIndex=0;b.dataset.liveUrl=resolveLiveUrl(x.url);b.title=x.label||`Transmissão ${i+1}`;b.setAttribute("aria-label",`Abrir ${x.label||"transmissão alternativa"} no YouTube`);b.textContent="▶";links.appendChild(b)});el.appendChild(links)}return el}
function render(){const on=document.getElementById("lives-on-container"),up=document.getElementById("lives-upcoming-container");if(!on||!up)return;on.replaceChildren();up.replaceChildren();const now=new Date(),labels={oficial:"🔴 Oficial",amador:"🟢 Amador",recomendada:"🔵 Recomendada",mobile:"📱 Mobile",emulador:"🖥️ Emulador",emulator:"🖥️ Emulador",misto:"🎮 Misto"};const visible=rows.map(r=>({r,s:statusFor(r,now)})).filter(x=>x.s.isLive||x.s.future).sort((a,b)=>{if(a.s.isLive!==b.s.isLive)return a.s.isLive?-1:1;return(a.s.start?.getTime()||0)-(b.s.start?.getTime()||0)}),liveItems=visible.filter(x=>x.s.isLive),upcomingItems=visible.filter(x=>!x.s.isLive);liveItems.forEach(({r,s})=>on.appendChild(buildLiveCard(r,s,now,labels)));upcomingItems.slice(0,upcomingVisible).forEach(({r,s})=>up.appendChild(buildLiveCard(r,s,now,labels)));const onEmpty=document.getElementById("lives-on-empty"),upEmpty=document.getElementById("lives-up-empty"),more=document.getElementById("lives-upcoming-more");if(onEmpty)onEmpty.style.display=liveItems.length?"none":"block";if(upEmpty)upEmpty.style.display=upcomingItems.length?"none":"block";if(more){more.hidden=upcomingItems.length<=upcomingVisible;more.textContent=`Ver próximas (${Math.min(UPCOMING_PAGE_SIZE,Math.max(0,upcomingItems.length-upcomingVisible))}) →`}}
async function fetchText(url,timeout=7000){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),timeout);try{const res=await fetch(url,{cache:"default",signal:ctl.signal});if(!res.ok)throw new Error(`HTTP ${res.status}`);return await res.text()}finally{clearTimeout(timer)}}
async function fetchJSON(url,timeout=7000){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),timeout);try{const res=await fetch(url,{cache:"default",signal:ctl.signal});if(!res.ok)throw new Error(`HTTP ${res.status}`);return await res.json()}finally{clearTimeout(timer)}}
async function loadAdmin(){const base=String(window.CFF_CONFIG?.firebase?.databaseURL||"").replace(/\/$/,"");if(!base){adminRows=[];return}try{adminRows=parseAdmin(await fetchJSON(`${base}/adminLives.json`))}catch(e){adminRows=[]}}
async function loadSheet(force=false){const base=window.CFF_CONFIG?.sheets?.lives;if(!base)return;const now=Date.now();if(!force&&sheetRows.length&&now-lastSheetFetch<300000)return;try{const text=await fetchText(base);sheetRows=parseSheet(text);lastSheetFetch=now}catch(e){if(!sheetRows.length)sheetRows=[]}}
async function load(opts={}){if(loading)return;loading=true;try{await Promise.all([loadAdmin(),loadSheet(!!opts.forceSheet)]);mergeRows();render()}catch(e){if(!opts.silent&&!rows.length)render()}finally{loading=false}}
window.loadLives=load;window.updateLivesTick=render;window.buildLivesHTML=render;
document.addEventListener("click",e=>{const alt=e.target.closest?.("[data-live-url]");if(alt){e.preventDefault();e.stopPropagation();window.open(alt.dataset.liveUrl,"_blank","noopener,noreferrer");return}const more=e.target.closest?.("#lives-upcoming-more");if(more){upcomingVisible+=UPCOMING_PAGE_SIZE;render()}});
document.addEventListener("keydown",e=>{const alt=e.target.closest?.("[data-live-url]");if(alt&&(e.key==="Enter"||e.key===" ")){e.preventDefault();e.stopPropagation();window.open(alt.dataset.liveUrl,"_blank","noopener,noreferrer")}});

function boot(){load();if(window.livesInterval)clearInterval(window.livesInterval);if(window.livesRefreshInterval)clearInterval(window.livesRefreshInterval);window.livesInterval=setInterval(render,30000);window.livesRefreshInterval=setInterval(()=>load({silent:true}),60000)}
document.readyState==="loading"?document.addEventListener("DOMContentLoaded",boot,{once:true}):boot();
})();
(()=>{if(document.getElementById('cff-home-live-standings-loader'))return;const s=document.createElement('script');s.id='cff-home-live-standings-loader';s.src='js/home-live-standings-v2.js?v=20260915-live-standings-v3';s.defer=true;document.head.appendChild(s)})();